use std::{collections::BTreeMap,fs};fn main(){let mut rows=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/affine-lp/CONTROL.stderr").unwrap().lines().filter(|l|l.starts_with("COUNT\t")){let v:Vec<_>=l.split('\t').collect();assert_eq!(v.len(),8);let n=|j:usize|v[j].parse::<u64>().unwrap();let c:Vec<u64>=v[7].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(c.len(),16);assert_eq!(c[8],2*c[7]+c[5]+c[6]);let k=(n(1),n(2),n(3),n(4));let value=(n(5),n(6),c);if k.2==1{assert_eq!(rows[&(k.0,k.1,0,k.3)],value)}assert!(rows.insert(k,value).is_none());}assert_eq!(rows.len(),24);println!("p\tsm\tell\tsparse_REDC\taffine_REDC\tsparse_over_affine_REDC\tsparse_inv\taffine_inv\taffine_hops");for(&(p,sm,rep,arm),(ell,_,a))in &rows{if rep!=0||arm!=0{continue}let(_,h,b)=&rows[&(p,sm,0,1)];println!("{p}\t{sm}\t{ell}\t{}\t{}\t{:.6}\t{}\t{}\t{h}",a[8],b[8],a[8]as f64/b[8]as f64,a[9],b[9]);}eprintln!("counted_calls=24 repeats_exact=true REDC_identity=true core0_first_determination_only=true");}
